     }
    ],
    "creator": {
     "name": "string",
     "email": "user@example.com"
    },
    "payer": {
     "name": "string",
     "email": "user@example.com"
    },
    "paid_amount": 0.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
